// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken, address newOwner) public {
        vm.assume(newOwner != address(0));

        // Add a reward token to ensure the contract is in a state where addReward can be called
        c.addReward(rewardToken);

        // Wrap transferOwnership in try/catch to detect reverts
        // The property is: calling transferOwnership with a non-zero address should NOT revert
        bool reverted = false;
        try c.transferOwnership(newOwner) {
            // success
        } catch {
            reverted = true;
        }

        assertTrue(!reverted, "transferOwnership should not revert when called with non-zero address");
    }
}

